select t.max_min,t.max_min maxMin,t.coupon_name,t.coupon_name couponName,t.ccp_id,t.ccp_id
ccpId,t.remark,t.status_cd,t.status_cd statusCd,t.store_id,t.store_id storeId,t.coupon_id,t.coupon_id
couponId,t.machine_name,t.machine_name machineName,t.machine_id,t.machine_id
machineId,t.create_time,t.create_time createTime,t.name,t.store_name,t.store_name storeName,t.min_min,t.min_min
minMin,t.state,t.community_id,t.community_id communityId
from charge_coupon_park t
where 1 =1

